    forCreators: 'Для креаторов',
    forCreatorsDesc: 'Мгновенная монетизация, финансирование сообщества, согласованные стимулы и пожизненный пассивный доход от успешного контента.',
    forFans: 'Для вентиляторов',
    forFansDesc: 'Финансовая выгода от поддержки восходящих звезд, торгуемых активов и прямого участия в успехе креаторов.',
    forEveryone: 'Для всех',
    forEveryoneDesc: 'Устойчивая к цензуре, система без разрешений, которая создает ценность для всех участников без зависимости от платформы.',
    comparisonSubtitle: 'Ключевое различие: создание остаточной и активной стоимости',
    comparisonDesc: 'В отличие от других платформ SocialFi, где креаторы должны постоянно добавлять ценность для своих токенов, акций или ключей, чтобы поддерживать ценность, контент DeHub генерирует остаточный доход на всю жизнь. Созданный контент приносит постоянный доход от рекламы, обеспечивая пассивный, беспроблемный, устойчивый к цензуре доход на всю вечность, не требуя постоянных усилий создателей.',
    thPlatform: 'Платформа',
    thContentModel: 'Модель контента',
    thValueCreation: 'Требование к созданию ценности',
    thRevenueModel: 'Модель дохода',
    thOwnership: 'Структура собственности',
    dehubModel: 'Опционально ERC-1155 Mint, фракционированный на 1000 штук на загрузку',
    dehubValue: 'НЕТ - Остаточный пожизненный доход',
