    flywheel4: 'Участники управления (избиратели по предложениям) получают небольшой прирост активности.',
    flywheelSummary: 'Это создает круговую экономику, которая стимулирует участие и стимулирует хорошее поведение',
    antiManipulation: 'Меры по борьбе с манипуляциями',
    anti1: 'Сопротивление Sybil: требует стейкинга + репутации для ключевых голосов.',
    anti2: 'Резервный совет с несколькими подписями: в случае неисправности DAO (только для чрезвычайных ситуаций).',
