    superPowersTitle: 'СуперСилами',
    superPowersDesc: 'Суперспособности превращают значок стейкинга в рич, который вы можете потратить. Каждые две недели ваш значок дает повышение, а тратя один, вы размещаете пост в слоте в верхней части домашней ленты. Команда открыта для всех и сочетает в себе силу кошелька до восьми учетных записей, давая каждому участнику значок их полной разблокировки. Слот вращается: когда выполняется несколько усилений, зрители получают один весовой уровень, поэтому более высокий уровень показывается чаще, и все по-прежнему получают окно, которое им было предоставлено.',
    superPowersDescV2: 'Суперспособности превращают значок стейкинга в рич, который вы можете потратить. Каждые две недели ваш значок дает повышение, а тратя один, вы размещаете пост в слоте в верхней части домашней ленты. Команда открыта для всех и сочетает в себе силу кошелька до восьми учетных записей, давая каждому участнику значок их полной разблокировки. Слот вращается: когда выполняется несколько усилений, зрители получают один весовой уровень, поэтому более высокий уровень показывается чаще, и все по-прежнему получают окно, которое им было предоставлено.',
    boostPower: '1) Усиление',
    boostPowerDesc: 'Разместите пост с прошлой недели в верхней части домашней ленты. Разблокируется в Crab. Живите сейчас.',
    secondWindPower: '2) Второе дыхание',
    secondWindPowerDesc: 'Отправьте публикацию старше недели обратно в верхнюю часть ленты. Разблокируется в Ghost Lobster. Живите сейчас.',
    trendJacker: '4) **Тренд-джекер**',
    trendJackerDesc2: 'Поставьте одну из своих категорий в верхней части списка трендов. Разблокируется у гигантской черепахи. Живите сейчас.',
    timelineBomber: '5) Бомбардировщик временной шкалы',
    timelineBomberDesc2: 'Ваши подписчики видят ваш пост впереди любого другого — королевская кобра побеждает мегалодона для людей, которые решили услышать вас. Разблокируется в King Cobra. Живите сейчас.',
    precisionStrike: '8) Точный удар',
    precisionStrikeDesc: 'Свяжитесь с людьми, которые следят за аккаунтом, который вы называете. Разблокируется в дельфинарии Dolphin. Живите сейчас.',
    harpoon: '9) Гарпун',
    harpoonDesc: 'Уведомляйте каждого владельца выбранных уровней бейджей об одном посту. Разблокировывается на уровне Тигровой акулы. Активно сейчас.',
    superPowersMore2: 'Все двенадцать полномочий находятся в режиме реального времени и перечислены в приложении. Анкор комментария удерживает ваш комментарий в верхней части чужой темы. Signal Flare отправляет одно уведомление каждой учетной записи, которая следует за вами. Flak Jacket делает пост невосприимчивым к погребению Downvote во время бега. Команда позволяет целых восьми учетным записям объединить свою силу кошелька, поэтому каждый участник носит значок, который разблокирует их объединенный баланс. Передний ряд помещает сцену, которую вы принимаете, в верхнюю часть направляющей сцены. Глубокий ток дает один из ваших импульсов к чужому посту.',
    superPowersMoreV2: 'Все двенадцать полномочий находятся в режиме реального времени и перечислены в приложении. Анкор комментария удерживает ваш комментарий в верхней части чужой темы. Signal Flare отправляет одно уведомление каждой учетной записи, которая следует за вами. Flak Jacket делает пост невосприимчивым к погребению Downvote во время бега. Команда позволяет целых восьми учетным записям объединить свою силу кошелька, поэтому каждый участник носит значок, который разблокирует их объединенный баланс. Передний ряд помещает сцену, которую вы принимаете, в верхнюю часть направляющей сцены. Глубокий ток дает один из ваших импульсов к чужому посту.',
    superPowersLink: 'Смотрите свое пособие и полную лестницу',
    spPowersTitle: 'Двенадцать сил',
    spPowersLead: 'Каждый шаг на лестнице достижений разблокирует ровно одну способность, и все разблокированные способности остаются доступными навсегда. Все они используют одно и то же еженедельное ограничение, поэтому выбор — за тем, на что потратить его.',
