    spQuantityOnly: 'Больше охвата, нет новой мощности',
    spRotationTitle: 'Как происходит совместное использование слота',
    spRotationDesc: 'Паз вращается, а не штифты. Когда одновременно выполняется несколько усилений, каждый зритель получает одно, взвешенное по уровню значка усилителя — более высокий уровень показывается чаще, и все по-прежнему получают окно, за которое они заплатили. То, что покупает Boost, - это доля голоса в течение определенного количества минут, а не единственное владение верхней частью ленты.',
    spCycleTitle: 'Одни часы для всех',
    spCycleDesc: 'Цикл представляет собой четырнадцать дней по всей платформе, поэтому все пособия пополняются в один и тот же момент. Ничего не перевернется. Отмените бронирование до его начала, и минуты вернутся в цикл, из которого вы их оплатили.',
    spSafetyTitle: 'Чего не может буст',
    spSafetyDesc: 'Каждая ничья повторно сверяется с публикацией в том виде, в котором она находится в данный момент, поэтому публикация, которая с тех пор была удалена, заблокирована или помечена как зрелая, никогда не попадает в ленту незнакомца. Зрелые публикации также отклоняются при бронировании, и бонус никогда не предоставляется тому, кто заблокировал вас или человека, которого вы повысили.',
