    badgeGreatWhiteShark: 'Большой значок белой акулы',
    badgeBlueWhale: 'Значок синего кита',
    badgeMegalodon: 'Медаль мегалодона',
    friendTechModel: 'Социальные ключи для доступа к чатам креаторов',
    friendTechValue: 'Требуется постоянное взаимодействие',
    friendTechRevenue: 'Основные торговые сборы, креатор сохраняет доход от чата',
    friendTechOwnership: 'Креатор владеет контентом, пользователи владеют ключами доступа',
    lensModel: 'NFT-базированный социальный граф с подписками/постами',
