    patreonOwnership: 'Автор владеет контентом, платформа контролирует его распространение',
    labelTokenGated: 'Токен-защищённый контент:',
    labelPPV: 'PPV-мероприятия:',
    labelNFT: 'NFT-коллекционные предметы:',
