    subtitle: 'Валюта, которая питает DeHub',
    intro: 'Токены DeHub - это собственная валюта утилиты сети DeHub; DHB - их тикерный символ. Это единая расчетная единица для каждого приложения — то, с чем вы даете чаевые, разблокируете контент, зарабатываете на просмотре и создании и тратите на генерацию ИИ. Поскольку они живут в сети, каждое движение стоимости в экосистеме подлежит публичной проверке, а не сидит в частной книге, в которой вы должны верить нам на слово.',
    howItWorksTitle: 'Как работает валюта в приложении',
    howItWorksDesc1: 'У каждого аккаунта DeHub есть встроенный кошелек. Вы можете пополнить его с помощью карты через наш шлюз Stripe, получить его от другого пользователя, заработать его на платформе или внести его с любого кошелька для самостоятельного хранения — для начала не требуется отдельного приложения, расширения или начальной фразы. Балансы, чаевые, разблокировка и вознаграждения рассчитываются в токенах DeHub, поэтому ценность перемещается между пользователями напрямую, а не направляется через платежный процессор, который сокращает и может заморозить учетную запись.',
    howItWorksDesc2: 'Удержание и стейкинг также меняют поведение приложения для вас. Чем больше у вас токенов DeHub, тем ниже плата за платформу и тем больше возможностей вы разблокируете — значки, подтверждение, повышение тренда, клубные уровни и расширенные права в сети. На практике валюта не является привязкой: это слой разрешений, планка вознаграждений и касса одновременно.',
