    useFeesTitle: 'Сборы, стейкинг и управление',
    useFeesDesc: 'Оплачивайте сетевые сборы, делайте ставки на клубные уровни для доли дохода от протокола и сжигайте токены DeHub, чтобы голосовать за управление решениями протокола.',
    profitShareTitle: 'Доля прибыли',
    profitShareDesc1: 'DeHub разработан таким образом, чтобы люди, использующие сеть, владели ею. Доход от протокола — плата за платформу, магазинные и рыночные сборы, реклама, использование ИИ и доход от игр — возвращается держателям акций в виде распределения реальной доходности и обратного выкупа, а не только что отчеканенного предложения. Таким образом, владение токенами DeHub - это владение долей самой сети DeHub, а не просто балансом расходов.',
    profitShareDesc2: 'Дистрибутивы финансируются из того, что на самом деле зарабатывает протокол, с переменными интервалами, и распределяются между уровнями стейкинга как по сумме, так и по продолжительности стейкинга. Более длительное обязательство приносит большую долю каждого распределения. Механику уровня и точный расчет вознаграждения см. в разделе Ставка.',
    pegTitle: 'Привязанная цена и объявление DEX',
    pegDesc1: 'Токен DeHub является служебным токеном. Для целей внутри приложения в настоящее время он привязан к $ 0,001 за токен, что является курсом, который вы видите при покупке через фиатный шлюз, и курсом, используемым для ценообразования внутри приложения. Эта привязка существует для поддержания стабильной и предсказуемой экономики в приложении во время масштабирования сети — это внутренняя учетная ставка, а не нижний предел, гарантия или обещание будущей ценности.',
    pegDesc2: 'Токен торгуется на децентрализованных биржах, при этом пулы ликвидности формируются из той же базовой цены 0,001 по нескольким цепочкам. На открытом рынке цена устанавливается путем торговли, а не DeHub, что означает, что токены DeHub могут торговаться выше или ниже привязки в приложении в любое время. DeHub формирует свою официальную ликвидность на DEX, чтобы каждая транзакция оставалась публично проверяемой в сети.',
